#include "cel_thumbnail_pipeline.h"
#include "document.h"
#include <stdexcept>
#include <iostream>
using namespace moon;
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
struct FakeLoop {
 using Callback=std::function<void()>;uint64_t next=1;double now=0;std::map<uint64_t,Callback> frames,deferred;
 CelThumbnailScheduler scheduler(){return {[this](Callback f){auto id=next++;frames.emplace(id,std::move(f));return id;},[this](Callback f){auto id=next++;deferred.emplace(id,std::move(f));return id;},[this](uint64_t id){frames.erase(id);},[this](uint64_t id){deferred.erase(id);},[this]{return now;}};}
 static void run(std::map<uint64_t,Callback>& q){require(!q.empty(),"Missing callback");auto i=q.begin();auto f=std::move(i->second);q.erase(i);f();}void tick(){if(!frames.empty())run(frames);if(!deferred.empty())run(deferred);}
};
int main(){try{
 CelThumbnailCache cache;CelThumbnailOwner owner=std::make_shared<int>(1);int builds=0;auto small=[&]{++builds;return CelThumbnailPixels{0xff0000ff};};auto first=cache.get(owner,"0",1,1,small);require(cache.get(owner,"0",0,1,small)==first&&builds==1,"Cache hit/revision wildcard");for(int i=1;i<8;++i)cache.get(owner,std::to_string(i),1,1,small);cache.get(owner,"0",1,1,small);cache.get(owner,"8",1,1,small);require(cache.variantCount(owner)==8&&builds==9,"Eight variants");cache.get(owner,"0",1,1,small);require(builds==10,"Cache hit reordered FIFO");cache.clear();cache.get(owner,"huge",1,1,[]{return CelThumbnailPixels(32769,0);});require(cache.cachedBytes(owner)==131076,"Soft byte budget");cache.get(owner,"small",1,1,small);require(cache.variantCount(owner)==1&&cache.cachedBytes(owner)==4,"Byte eviction");first=cache.get(owner,"live",1,1,small);require((*cache.get(owner,"live",1,1,[]{return CelThumbnailPixels{7};},true))[0]==7&&cache.get(owner,"live",1,1,small)==first,"Live bypass");const int before=builds;cache.get(owner,"live",2,1,small);cache.get(owner,"live",0,2,small);require(builds==before+2,"Revision invalidation");auto alias=owner;owner.reset();require(cache.ownerCount()==1,"Owner alias");alias.reset();require(cache.ownerCount()==0&&!first->empty(),"Weak lifetime");
 FakeLoop loop;CelThumbnailQueue queue(loop.scheduler());int done=0;for(int i=0;i<65;++i)queue.schedule([&]{++done;});require(loop.frames.size()==1&&loop.deferred.empty(),"Frame wake");FakeLoop::run(loop.frames);require(done==0&&loop.deferred.size()==1,"Deferred phase");FakeLoop::run(loop.deferred);require(done==64&&queue.pending()==1,"64 batch");loop.tick();require(done==65&&queue.pending()==0,"Remainder");int timed=0;for(int i=0;i<3;++i)queue.schedule([&]{++timed;loop.now+=4;});loop.tick();require(timed==2&&queue.pending()==1,"8ms budget");loop.tick();auto cancel=queue.schedule([]{throw std::runtime_error("Canceled task ran");});cancel();cancel();require(queue.pending()==0&&loop.frames.empty()&&loop.deferred.empty(),"Cancel final task");auto cancelDeferred=queue.schedule([]{throw std::runtime_error("Canceled deferred ran");});FakeLoop::run(loop.frames);cancelDeferred();require(loop.deferred.empty(),"Cancel deferred");CelThumbnailQueue::Cancel after;{CelThumbnailQueue temporary(loop.scheduler());after=temporary.schedule([]{});}after();require(loop.frames.empty(),"Destruction cancels");queue.schedule([]{throw std::runtime_error("fixture");});queue.schedule([&]{++done;});bool threw=false;try{loop.tick();}catch(...){threw=true;}require(threw&&queue.pending()==1,"Exception reschedule");loop.tick();require(done==66,"Exception remainder");
 Document document(2,1);document.beginStroke({0,0},0xffabcdef);document.commitStroke();const auto sourceId=document.cel().id;auto original=document.timeline().thumbnailStorage(document.cel().id);document.addLinkedFrame(false);auto linked=document.timeline().thumbnailStorage(document.cel().id);auto source=document.timeline().thumbnailStorage(sourceId);require(linked.owner==source.owner,"Linked storage token");auto old=linked;document.beginStroke({0,0},0xff123456);document.commitStroke();linked=document.timeline().thumbnailStorage(document.cel().id);require(linked.owner==old.owner&&linked.revision>old.revision,"Targeted stroke revision");old=linked;document.undo();linked=document.timeline().thumbnailStorage(document.cel().id);require(linked.owner!=old.owner||linked.revision>old.revision,"Undo invalidates");timeline::Timeline copy(document.timeline());require(copy.thumbnailStorage(document.cel().id).owner!=linked.owner,"Deep copy storage token");
 std::cout<<"Thumbnail pipeline fixtures passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
